-------------------------------------------------------------------------------------------------------------------------------------------------------------
-- configuration file for EW Script 3.0 (Timberwolf's EA-18G AEA script) Plugin
--
-- This configuration is tailored for a mission generated by DCS Retribution
-- see https://github.com/dcs-retribution/dcs-retribution
-------------------------------------------------------------------------------------------------------------------------------------------------------------

AEA_options = AEA_options or {}

if dcsRetribution and dcsRetribution.plugins and dcsRetribution.plugins.EWScript3 then
    local p = dcsRetribution.plugins.EWScript3
    local keys = {
        "players_enabled", "ai_enabled", "ai_window_gating", "ai_jam_search",
        "ai_protect_radius_nm", "ai_hold_sec", "range_multiplier",
        "missile_disrupt_chance", "missile_disrupt_nm", "air_effects",
        "spj_enabled", "spj_internal_ecm", "spj_players", "spj_missile_chance", "spj_missile_nm",
        "DEBUG_LOG", "DEBUG_MESSAGES", "DEBUG_VERBOSE",
    }
    for _, k in ipairs(keys) do
        if p[k] ~= nil then
            AEA_options[k] = p[k]
        end
    end

    env.info("DCS Retribution | EW Script 3.0 - Setting Up")
    if AEA_options.DEBUG_LOG then
        for _, k in ipairs(keys) do
            env.info("[EWS3] option " .. k .. " = " .. tostring(AEA_options[k]))
        end
    end

    -- EW Script 2.1 (ewrj) and EW Script 3.0 are independent and both act on SAM ROE and
    -- incoming missiles. They are not meant to be enabled together.
    if dcsRetribution.plugins.ewrj then
        local warn = "WARNING: EW Script 2.1 and EW Script 3.0 are both enabled. "
            .. "Both scripts will act on SAMs and missiles independently - enable only one of them."
        env.warning("[EWS3] " .. warn)
        trigger.action.outText(warn, 30)
    end
end
